@vulnerabilities_app.command('list', help='List vulnerabilities.\n\nLists vulnerability findings in an active registry, with optional filters. Paged with `page` and `page_size` (at most 100). Requires scope: container-registry.read.\n\nAPI: GET /container-registry/registries/{registry_id}/security/vulnerabilities (listContainerRegistryVulnerabilities).', short_help='List vulnerabilities')
@handle_api_errors
def list_container_registry_vulnerabilities(
    ctx: typer.Context,
    registry_id: str = typer.Argument(..., metavar='REGISTRY_ID', show_default=False, help='Registry ID.'),
    severity: Optional[str] = typer.Option(None, '--severity', show_default=False, help='Return only findings of this severity. - `Critical` - `High` - `Medium` - `Low` - `Unknown` - `None`'),
    cve_id: Optional[str] = typer.Option(None, '--cve-id', show_default=False, help='Return only findings for this CVE or advisory ID.'),
    repository_name: Optional[str] = typer.Option(None, '--repository-name', show_default=False, help='Return only findings on artifacts in this repository.'),
    digest: Optional[str] = typer.Option(None, '--digest', show_default=False, help='Return only findings on the artifact with this digest.'),
    tag: Optional[str] = typer.Option(None, '--tag', show_default=False, help='Return only findings on artifacts carrying this tag.'),
    package: Optional[str] = typer.Option(None, '--package', show_default=False, help='Return only findings in this package.'),
    page: Optional[int] = typer.Option(None, '--page', show_default=False, help='Page number.'),
    page_size: Optional[int] = typer.Option(None, '--page-size', show_default=False, help='Number of records per page.'),
) -> None:
    client = sdk(ctx)
    result = client.container_registry.list_container_registry_vulnerabilities(
        registry_id,
        **compact(
            workspace_id=workspace(ctx),
            severity=severity,
            cve_id=cve_id,
            repository_name=repository_name,
            digest=digest,
            tag=tag,
            package=package,
            page=page,
            page_size=page_size,
        ),
    )
    emit(result, collection='items')


@sboms_app.command('list', help='List SBOMs.\n\nLists the SBOMs of one repository, one per image digest. Paged with `page` and `page_size` (at most 100). Requires scope: container-registry.read.\n\nAPI: GET /container-registry/registries/{registry_id}/security/sboms (listContainerRegistrySboms).', short_help='List SBOMs')
@handle_api_errors
def list_container_registry_sboms(
    ctx: typer.Context,
    registry_id: str = typer.Argument(..., metavar='REGISTRY_ID', show_default=False, help='Registry ID.'),
    repository_name: str = typer.Option(..., '--repository-name', show_default=False, help='Repository name inside the registry, for example `api` or `team/api`.'),
    page: Optional[int] = typer.Option(None, '--page', show_default=False, help='Page number.'),
    page_size: Optional[int] = typer.Option(None, '--page-size', show_default=False, help='Number of records per page.'),
) -> None:
    client = sdk(ctx)
    result = client.container_registry.list_container_registry_sboms(
        registry_id,
        **compact(
            workspace_id=workspace(ctx),
            repository_name=repository_name,
            page=page,
            page_size=page_size,
        ),
    )
    emit(result, collection='items', id_field='artifact_digest')


@sboms_app.command('get', help="Get SBOM.\n\nReturns one image's SBOM components and their relationships. `q` filters components by name, version, type, license, supplier or package URL. Components are paged with `page` and `page_size` (at most 100). Requires scope: container-registry.read.\n\nAPI: GET /container-registry/registries/{registry_id}/security/sboms/{artifact_digest} (getContainerRegistrySbom).", short_help='Get SBOM')
@handle_api_errors
def get_container_registry_sbom(
    ctx: typer.Context,
    registry_id: str = typer.Argument(..., metavar='REGISTRY_ID', show_default=False, help='Registry ID.'),
    artifact_digest: str = typer.Argument(..., metavar='ARTIFACT_DIGEST', show_default=False, help='Image digest, for example `sha256:4f3c...`.'),
    repository_name: str = typer.Option(..., '--repository-name', show_default=False, help='Repository name inside the registry, for example `api` or `team/api`.'),
    q: Optional[str] = typer.Option(None, '--q', show_default=False, help='Component search text.'),
    page: Optional[int] = typer.Option(None, '--page', show_default=False, help='Page number.'),
    page_size: Optional[int] = typer.Option(None, '--page-size', show_default=False, help='Number of records per page.'),
) -> None:
    client = sdk(ctx)
    result = client.container_registry.get_container_registry_sbom(
        registry_id,
        artifact_digest,
        **compact(
            workspace_id=workspace(ctx),
            repository_name=repository_name,
            q=q,
            page=page,
            page_size=page_size,
        ),
    )
    emit(result)


@sboms_app.command('download', help="Download SBOM.\n\nDownloads one image's full SBOM document as a JSON attachment (SPDX or CycloneDX). Requires scope: container-registry.read.\n\nAPI: GET /container-registry/registries/{registry_id}/security/sboms/{artifact_digest}/download (downloadContainerRegistrySbom).", short_help='Download SBOM')
@handle_api_errors
def download_container_registry_sbom(
    ctx: typer.Context,
    registry_id: str = typer.Argument(..., metavar='REGISTRY_ID', show_default=False, help='Registry ID.'),
    artifact_digest: str = typer.Argument(..., metavar='ARTIFACT_DIGEST', show_default=False, help='Image digest, for example `sha256:4f3c...`.'),
    repository_name: str = typer.Option(..., '--repository-name', show_default=False, help='Repository name inside the registry, for example `api` or `team/api`.'),
) -> None:
    client = sdk(ctx)
    result = client.container_registry.download_container_registry_sbom(
        registry_id,
        artifact_digest,
        **compact(
            workspace_id=workspace(ctx),
            repository_name=repository_name,
        ),
    )
    write_bytes(result)


@app.command('metrics', help='Get registry metrics.\n\nReturns storage use against the plan quota and outbound bandwidth over the last 24 hours, 7 days or 30 days. Bytes are decimal (1 GB = 1,000,000,000 bytes). Requires scope: container-registry.read.\n\nAPI: GET /container-registry/registries/{registry_id}/metrics (getContainerRegistryMetrics).', short_help='Get registry metrics')
@handle_api_errors
def get_container_registry_metrics(
    ctx: typer.Context,
    registry_id: str = typer.Argument(..., metavar='REGISTRY_ID', show_default=False, help='Registry ID.'),
    range_: Optional[str] = typer.Option(None, '--range', show_default=False, help='Time window. One of: 24h, 7d, 30d.'),
) -> None:
    client = sdk(ctx)
    result = client.container_registry.get_container_registry_metrics(
        registry_id,
        **compact(
            workspace_id=workspace(ctx),
            range=range_,
        ),
    )
    emit(result)
